// SealedModels.kt
// CarrierPony Android
//
// The sealed-sender state models: per-pair state, per-group state, and the route
// a registered receive address resolves to. Pure Kotlin with no Android imports,
// split out of SealedKeyStore.kt (a move, no behavior change) so the desktop
// client can compile these exact classes while supplying its own key store.

package com.carrierpony.app.messaging

import com.carrierpony.app.crypto.Fingerprint
import org.json.JSONObject
import kotlin.io.encoding.Base64

/** Per-pair sealed state for one peer. myInboundKey is generated by this device
 *  and handed to the peer (they address us with it; we register and derive our
 *  receive addresses from it). peerInboundKey arrives from the peer; we address
 *  them with it. Counters advance per direction. canSend once peerInboundKey set. */
class SealedPairState(
    val myInboundKey: ByteArray,
    val peerInboundKey: ByteArray?,
    val sendCounter: Long,
    val receiveHigh: Long,
    val sharedMine: Boolean
) {
    val canSend: Boolean get() = peerInboundKey != null

    fun toJson(): String {
        val j = JSONObject()
        j.put("mine", Base64.Default.encode(myInboundKey))
        if (peerInboundKey != null) j.put("peer", Base64.Default.encode(peerInboundKey))
        j.put("send", sendCounter)
        j.put("recv", receiveHigh)
        j.put("shared", sharedMine)
        return j.toString()
    }

    companion object {
        fun fromJson(s: String): SealedPairState? = try {
            val j = JSONObject(s)
            SealedPairState(
                myInboundKey = Base64.Default.decode(j.getString("mine")),
                peerInboundKey = j.optString("peer").takeIf { it.isNotEmpty() }?.let { Base64.Default.decode(it) },
                sendCounter = j.optLong("send"),
                receiveHigh = j.optLong("recv"),
                sharedMine = j.optBoolean("shared")
            )
        } catch (e: Exception) {
            null
        }
    }
}

/** Sealed group delivery state, per group and epoch: my outbound counter to each
 *  member, and the high-water of what I have received from each member. Reset
 *  when the epoch rotates, since the address space changes with the key. */
class SealedGroupState(
    val epoch: Int,
    val sendCounters: MutableMap<String, Long>,
    val recvHighs: MutableMap<String, Long>
) {
    fun toJson(): String {
        val send = org.json.JSONObject()
        for ((k, v) in sendCounters) send.put(k, v)
        val recv = org.json.JSONObject()
        for ((k, v) in recvHighs) recv.put(k, v)
        return org.json.JSONObject().put("epoch", epoch).put("send", send).put("recv", recv).toString()
    }

    companion object {
        fun fromJson(s: String): SealedGroupState? = try {
            val j = org.json.JSONObject(s)
            SealedGroupState(
                epoch = j.getInt("epoch"),
                sendCounters = longMap(j.optJSONObject("send")),
                recvHighs = longMap(j.optJSONObject("recv"))
            )
        } catch (e: Exception) {
            null
        }

        private fun longMap(o: org.json.JSONObject?): MutableMap<String, Long> {
            val m = mutableMapOf<String, Long>()
            if (o != null) {
                val it = o.keys()
                while (it.hasNext()) { val k = it.next(); m[k] = o.getLong(k) }
            }
            return m
        }
    }
}

/** A registered receive address routes to a 1:1 pair stream or a group stream
 *  (identified by the group and the co-member who sends on it). */
sealed class SealedRoute {
    data class PairRoute(val peer: Fingerprint, val counter: Long) : SealedRoute()
    data class GroupRoute(val groupID: String, val sender: Fingerprint, val counter: Long) : SealedRoute()
}
